<div class="page-heading"><div><a href="index.php" class="back-link">← Все базы</a><h1><?= $e($import['name']) ?></h1><p class="muted"><?= number_format((int)$import['row_count'],0,',',' ') ?> контактов · <?= $e(strtoupper($import['source_type'])) ?> · <?= $e(date('d.m.Y',strtotime($import['created_at']))) ?></p></div><div class="actions"><a class="button" href="<?= $e($url('export',['id'=>$import['id'],'format'=>'xls'])) ?>">↓ XLS</a><a class="button primary" href="<?= $e($url('export',['id'=>$import['id'],'format'=>'csv'])) ?>">↓ CSV</a></div></div>
<section class="card data-card"><div class="table-toolbar"><div class="tabs"><a class="<?= !$raw?'selected':'' ?>" href="<?= $e($url('table',['id'=>$import['id']])) ?>">Унифицированная</a><a class="<?= $raw?'selected':'' ?>" href="<?= $e($url('table',['id'=>$import['id'],'view'=>'raw'])) ?>">Как есть</a></div><form method="get" class="search-form"><input type="hidden" name="a" value="table"><input type="hidden" name="id" value="<?= $e($import['id']) ?>"><input type="hidden" name="view" value="<?= $raw?'raw':'normalized' ?>"><input name="q" value="<?= $e($search) ?>" placeholder="Поиск в этой базе" aria-label="Поиск в базе"><button class="button">Найти</button></form></div>
<div class="table-scroll"><table class="<?= $raw?'raw-table':'normalized' ?>"><thead><tr><?php foreach ($raw?json_decode($import['headers_json'],true):Contacts\Normalizer::FIELDS as $h): ?><th><?= $e($h) ?></th><?php endforeach ?></tr></thead><tbody>
<?php foreach ($rows as $row): ?><tr><?php if ($raw): ?><?php foreach (json_decode($row['raw_json'],true) as $v): ?><td><?= $e($v) ?></td><?php endforeach ?><?php else: ?>
<td><a class="company-link" href="<?= $e($url('note',['id'=>$row['id']])) ?>"><?= $e($row['company']) ?: 'Без названия' ?></a></td><td><?= $e($row['address']) ?: '<span class="muted">—</span>' ?></td>
<td><?php foreach (array_filter(explode('; ', $row['phones'])) as $phone): ?><?php $tel=Contacts\Normalizer::tel($phone); ?><div class="contact-line"><?php if ($phoneAction==='form' || $tel): ?><a href="<?= $e($phoneAction==='form'?$url('note',['id'=>$row['id'],'phone'=>$phone]):$tel) ?>"><?= $e($phone) ?></a><?php else: ?><?= $e($phone) ?><?php endif ?></div><?php endforeach ?><?php if (!$row['phones']): ?><span class="muted">—</span><?php endif ?></td>
<td><?php foreach (array_filter(explode('; ', $row['email'])) as $email): ?><div class="contact-line"><?php if (filter_var($email,FILTER_VALIDATE_EMAIL)): ?><a href="<?= $e('mailto:'.$email) ?>"><?= $e($email) ?></a><?php else: ?><?= $e($email) ?><?php endif ?></div><?php endforeach ?><?php if (!$row['email']): ?><span class="muted">—</span><?php endif ?></td>
<td><?php foreach (array_filter(explode('; ', $row['website'])) as $site): ?><div class="contact-line"><?php if (Contacts\Normalizer::websiteLink($site)): ?><a href="<?= $e($site) ?>" target="_blank" rel="noopener noreferrer"><?= $e(preg_replace('~^https?://~','',$site)) ?> ↗</a><?php else: ?><?= $e($site) ?><?php endif ?></div><?php endforeach ?><?php if (!$row['website']): ?><span class="muted">—</span><?php endif ?></td>
<?php endif ?></tr><?php endforeach ?>
<?php if (!$rows): ?><tr><td colspan="<?= $raw?count(json_decode($import['headers_json'],true)):5 ?>" class="empty">Контакты не найдены. Измените поисковый запрос.</td></tr><?php endif ?>
</tbody></table></div><div class="pagination"><span class="muted">Найдено <?= $count ?> · Страница <?= $page ?> из <?= $pages ?></span><div class="actions"><?php if ($page>1): ?><a class="button" href="<?= $e($url('table',['id'=>$import['id'],'view'=>$raw?'raw':'normalized','q'=>$search,'page'=>$page-1])) ?>">← Назад</a><?php endif ?><?php if ($page<$pages): ?><a class="button" href="<?= $e($url('table',['id'=>$import['id'],'view'=>$raw?'raw':'normalized','q'=>$search,'page'=>$page+1])) ?>">Далее →</a><?php endif ?></div></div></section>
<section class="card integration"><div><div class="eyebrow">ИНТЕГРАЦИЯ</div><h2>Открыть базу в Google Таблицах</h2><p class="muted">CSV-ссылка отдаёт все контакты этой загрузки в пяти колонках. Поиск на странице не ограничивает экспорт.</p></div>
<?php if ($feedUrl && $activeFeed): ?><label>CSV-ссылка<div class="copy-row"><input readonly value="<?= $e($feedUrl) ?>" id="feed-link"><button type="button" class="button" data-copy="feed-link">Скопировать</button></div></label><label>Формула для ячейки A1<div class="copy-row"><input readonly value="<?= $e('=IMPORTDATA("'.$feedUrl.'")') ?>" id="feed-formula"><button type="button" class="button" data-copy="feed-formula">Скопировать</button></div></label><?php elseif ($activeFeed): ?><p>Ссылка активна. Её адрес был показан при создании. Чтобы получить новый адрес, перевыпустите ссылку.</p><?php endif ?>
<p class="hint">Контакты доступны каждому, у кого есть эта ссылка. Google может кэшировать данные. После отзыва ссылки уже скопированные данные останутся в Google.</p><div class="actions"><form method="post" action="<?= $e($url('feed_create',['id'=>$import['id']])) ?>" <?= $activeFeed?'data-confirm="Предыдущая ссылка перестанет работать. Выпустить новую?"':'' ?>><?= self::csrf() ?><button class="button"><?= $activeFeed?'Перевыпустить ссылку':'Создать CSV-ссылку' ?></button></form><?php if ($activeFeed): ?><form method="post" action="<?= $e($url('feed_revoke',['id'=>$import['id']])) ?>" data-confirm="Отозвать доступ по CSV-ссылке?"><?= self::csrf() ?><button class="button danger">Отозвать ссылку</button></form><?php endif ?></div></section>
